const rows = $('Traer conversaciones del dia').all().map(i => i.json);
const adSessions = new Set($input.all().map(i => i.json.session_id));

const bySession = {};
for (const r of rows) {
  if (!bySession[r.session_id]) bySession[r.session_id] = [];
  bySession[r.session_id].push({ role: r.role, content: r.content });
}

// Biotina Pura - precios por cantidad y costo real (costo de producto +
// envio por pedido, el envio no se multiplica por unidad)
const UNIDADES_POR_MONTO = { 35000: 1, 45000: 2, 60000: 3 };
const COSTO_PRODUCTO_UNIT = 3500;
const COSTO_ENVIO_POR_PEDIDO = 10000;
// Fallback para conversaciones viejas del Combo Biotina (precio fijo, ya
// no se vende, pero puede quedar alguna en el dia de la migracion)
const PRECIO_FALLBACK = 43000;
const COSTO_FALLBACK = 10000;

function gananciaDeVenta(monto) {
  const unidades = UNIDADES_POR_MONTO[monto];
  if (unidades) return monto - (COSTO_PRODUCTO_UNIT * unidades + COSTO_ENVIO_POR_PEDIDO);
  return monto - COSTO_FALLBACK;
}

// Numeros del dueno y del equipo (Dolores) - no son clientes reales, se
// excluyen aunque hayan entrado marcados como origen de anuncio (pruebas)
const EXCLUDED_NUMBERS = new Set(['TU_NUMERO_PERSONAL_AQUI', 'NUMERO_DOLORES_AQUI']);

let totalConversaciones = 0;
let ventasCerradas = 0;
let facturacion = 0;
let ganancia = 0;

for (const [sessionId, msgs] of Object.entries(bySession)) {
  if (!adSessions.has(sessionId)) continue; // solo conversaciones iniciadas por un anuncio hoy
  const numberOnly = sessionId.split('@')[0];
  if (EXCLUDED_NUMBERS.has(numberOnly)) continue;
  totalConversaciones++;
  const paymentMsg = msgs.find(m => m.role === 'assistant' && (m.content.includes('CBU: 3840200500000054291199') || m.content.includes('Alias: productoscapilarespg')));
  const sentReceipt = msgs.some(m => m.role === 'user' && m.content.includes('Imagen recibida'));
  if (paymentMsg && sentReceipt) {
    ventasCerradas++;
    const montoMatch = paymentMsg.content.match(/\$\s?([\d.]+)/);
    const monto = montoMatch ? parseInt(montoMatch[1].replace(/\./g, ''), 10) : PRECIO_FALLBACK;
    facturacion += monto;
    ganancia += gananciaDeVenta(monto);
  }
}

const conversionPct = totalConversaciones > 0 ? ((ventasCerradas / totalConversaciones) * 100).toFixed(1) : '0.0';
const fmt = n => n.toLocaleString('es-AR');

const hoy = new Date().toLocaleDateString('es-AR', { timeZone: 'America/Argentina/Buenos_Aires', day: '2-digit', month: '2-digit', year: 'numeric' });

let text = `\u{1F4C5} Resumen del dia (${hoy})\n\n`;
text += `\u{1F4AC} Conversaciones desde anuncios: ${totalConversaciones}\n`;
text += `\u{1F6D2} Ventas cerradas: ${ventasCerradas}\n`;
text += `\u{1F4C8} Conversion: ${conversionPct}%\n`;
if (ventasCerradas > 0) {
  text += `\u{1F4B0} Facturacion: $${fmt(facturacion)}\n`;
  text += `\u{2705} Ganancia neta: $${fmt(ganancia)}`;
} else {
  text += `\u{1F4B0} Sin ventas cerradas hoy.`;
}

return [{ json: { text } }];

